CREATE OR REPLACE FUNCTION public.update_workspace(p_workspace_id uuid, p_name text, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.workspaces;
begin
 if not baya_private.owns_workspace(p_workspace_id) then raise exception 'unauthorized' using errcode='42501'; end if;
 if p_name is null or char_length(btrim(p_name)) not between 1 and 100 or p_status is null or p_status not in ('active','archived') then
 raise exception 'invalid_workspace' using errcode='22023';
 end if;
 update public.workspaces set workspace_name=btrim(p_name),status=p_status where workspace_id=p_workspace_id returning * into w;
 return to_jsonb(w)||jsonb_build_object('learnerCount',(select count(*) from public.workspace_memberships where workspace_id=p_workspace_id and is_active));
end $function$

CREATE OR REPLACE FUNCTION public.set_workspace_member_active(p_workspace_id uuid, p_profile_id uuid, p_active boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not baya_private.owns_workspace(p_workspace_id) then raise exception 'unauthorized' using errcode='42501'; end if;
 if p_active is null then raise exception 'invalid_membership' using errcode='22023'; end if;
 update public.workspace_memberships set is_active=p_active where workspace_id=p_workspace_id and learner_profile_id=p_profile_id;
 if not found then raise exception 'not_found' using errcode='P0002'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.create_workspace(p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m uuid := baya_private.own_mentor(); w public.workspaces; i integer;
begin
 if m is null then raise exception 'unauthorized' using errcode='42501'; end if;
 if p_name is null or char_length(btrim(p_name)) not between 1 and 100 then raise exception 'invalid_name' using errcode='22023'; end if;
 for i in 1..5 loop
 begin
 insert into public.workspaces(mentor_profile_id,workspace_name,workspace_code)
 values(m,btrim(p_name),'BAYA-'||upper(left(replace(gen_random_uuid()::text,'-',''),12))) returning * into w;
 return to_jsonb(w)||jsonb_build_object('learnerCount',0);
 exception when unique_violation then null;
 end;
 end loop;
 raise exception 'conflict' using errcode='23505';
end $function$

CREATE OR REPLACE FUNCTION public.list_owned_workspaces()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m uuid := baya_private.own_mentor(); result jsonb;
begin
 if m is null then raise exception 'unauthorized' using errcode='42501'; end if;
 select coalesce(jsonb_agg(to_jsonb(w)||jsonb_build_object('learnerCount',(select count(*) from public.workspace_memberships wm where wm.workspace_id=w.workspace_id and wm.is_active)) order by w.created_at desc),'[]'::jsonb)
 into result from public.workspaces w where w.mentor_profile_id=m;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.get_workspace_details(p_workspace_id uuid)
 RETURNS jsonb
